    proof {

        block_start_at_diff(page_id, bsize as nat, capacity as nat, (capacity + extend) as nat);

        preserves_mem_chunk_good_on_transfer_to_capacity(*old(local), *local, page_id);
        assert(local.mem_chunk_good(segment_id));
